/usr/bin/zsh -lc "python3 -c 'import os,hashlib,json; p=\"/home/tcuni-claw/pi/pi-planner-only/index.ts\"; digest=lambda:hashlib.sha256(open(p,\"rb\").read()).hexdigest(); before=digest(); result={\"path\":p,\"sha256_before\":before};
try:
 fd=os.open(p,os.O_WRONLY); os.close(fd); result.update(open_succeeded=True,errno=None)
except OSError as e:
 result.update(open_succeeded=False,errno=e.errno,error=str(e))
mounts=[]
for line in open(\"/proc/self/mountinfo\"):
 parts=line.split(); mount=parts[4].replace(\"\\\\040\",\" \");
 if p==mount or p.startswith(mount.rstrip(\"/\")+\"/\"): mounts.append((len(mount),line.strip()))
result[\"covering_mount\"]=max(mounts)[1] if mounts else None; result[\"sha256_after\"]=digest(); result[\"unchanged\"]=before==result[\"sha256_after\"]; print(json.dumps(result))'"

